CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(255) NOT NULL);
ALTER TABLE items ADD COLUMN IF NOT EXISTS name VARCHAR(255), ADD COLUMN IF NOT EXISTS price INT;
ALTER TABLE items DROP COLUMN IF EXISTS missing_column;
ALTER TABLE items MODIFY COLUMN IF EXISTS missing_column INT;
ALTER TABLE items CHANGE COLUMN IF EXISTS missing_column other INT;
ALTER TABLE IF EXISTS gone ADD COLUMN extra INT;
ALTER TABLE items MODIFY COLUMN price INT FIRST;
ALTER TABLE items ADD COLUMN note TEXT AFTER price;
CREATE TABLE items_copy LIKE items;
